namespace WorldCreator;

internal static class EditorHelp
{
    internal static readonly string[] Titles =
    {
        "Overview",
        "Environment",
        "Weather",
        "Orbit & seasons",
        "Resources",
        "Terrain",
        "Advanced",
        "Map studio",
        "Starting conditions",
        "Asset libraries",
        "Asset Creator"
    };
    internal static readonly (string Title, string Body)[] GettingStarted =
    {
        ("1. Begin with a blank world", "Choose Create a New World on the World Creator start page. A blank world has basic editable settings, a temperature curve and a default starting-profile reference. It does not generate a complete custom terrain. You can build it without applying an original-world preset."),
        ("2. Give the world an identity", "On Overview, enter a display name such as First World and a unique ID such as FirstWorld. The editor accepts 1–47 letters, numbers or underscores. No prefix is required; WC_ is only an optional naming convention. Add a description and choose gravity. For example, -3.7 means a weaker downward pull than -9.81. Keep the same World ID while finishing this project."),
        ("3. Supply the terrain", "Open Terrain, then Open Terrain Tools. World Creator hides so you can use the game's terrain utility. Import and compile terrain with the size expected by this world, saving its indexed Terrain<number>.dat files to a folder. Reopen World Creator from the main menu, enter that folder on Terrain and choose Use compiled terrain. A painted region map alone does not create terrain geometry."),
        ("4. Set the orbit and landing reference", "On Orbit & seasons, choose the available orbital distance, period, shape and orientation values. Keep eccentricity below 1 for an elliptical orbit. Set latitude between -90 and 90 degrees and longitude between -180 and 180 degrees. Use the orbit and Landing site views to inspect the result. Camera rotation, zoom, phase and Simulate are preview controls; they do not save a new starting time into the world."),
        ("5. Build the atmosphere", "On Environment, choose a gas, enter its amount in moles and press Add gas. Quantities describe each 8,000-litre atmosphere cell. Set the base-temperature points between 0 and 180 degrees of sun angle. Temperature units are display choices; the world stores kelvin. Inspect the pressure estimate and combined-temperature preview. Configure solar, greenhouse and density offsets in worlds that define them."),
        ("6. Choose weather", "On Weather, add an installed event or create your own. Set cooldown in game days, and start delay and duration in seconds. Remove an event from the world to exclude it. To reuse a custom event in other projects, choose Save to My Weather on its settings card. A blank world can also remain without weather events."),
        ("7. Prepare gear, maps and assets", "On Starting conditions, keep the default profile or add a copy of an installed profile and customize it. Add supply crates and item quantities where needed. On Map studio, create or edit region masks only if your design needs them. Import reusable files through Asset libraries, add project copies, and assign their displayed paths to the settings that use them. If you need a particular ore layout, check the matching resource definitions and region links as well."),
        ("8. Create and try the world mod", "Press Create world mod in the footer. Export errors show the affected item or field in orange with a cross; use Show affected field or Open page to find its settings. The output is a world-definition mod in your local Stationeers mods folder, not a saved game. Restart Stationeers, enable that generated world mod in LaunchPad, then choose it when starting a New World. To revise a local World Creator export, use Load a World and keep its World ID. Update world mod replaces it after confirmation and retains the previous folder under WorldCreator/ExportBackups outside mods. Change World ID to create a separate copy. Workshop originals cannot be updated through this action.")
    };
    internal static readonly (string Title, string Body)[][] Pages =
    {
        new (string Title, string Body)[]
        {
            ("What Overview is for", "Overview identifies the world and sets its main presentation options. The World Project header refers to the same project on every page. The summary tiles count or display existing settings; they are not separate inputs. Continue building buttons take you to the page that edits each part."),
            ("Display name, World ID and description", "Display name is the name players see in the world menu. World ID is the identifier used by XML references and the generated mod. Choose a unique ID with 1–47 letters, numbers or underscores; no prefix is required. WC_ is optional. Avoid reusing an ID from another installed world. Description is the longer text shown for the world. The multiline box accepts several paragraphs. Names are readable text; IDs must remain exact and unique."),
            ("Gravity", "Gravity uses metres per second squared. Stationeers world definitions use a negative value for downward gravity: -9.81 has a stronger pull than -3.7. Change the value itself to alter the world. Orbiting the preview camera or changing the planet's displayed size does not change gravity."),
            ("Starting from an original world", "Select an installed world in Start from an original world and press Apply preset. Confirming replaces the current project with that selected template. Apply it before making custom changes you want to keep. To work entirely from scratch, leave this card unused. Load a World on the start page instead reads a world definition from a local or Workshop mod; it does not load a saved play session."),
            ("World list and visibility", "World list priority influences where the definition appears in the game's list. The visibility checkbox is backed by the XML Hidden flag: enabling that flag hides the world from normal selection. Keep a world visible while checking that a newly created mod appears in New World. Priority and visibility do not change terrain, difficulty or atmospheric conditions."),
            ("Primary body, lighting and appearance", "Primary body ID identifies the central body used by the orbital simulation; when the XML omits it, the game uses Sol. Primary star irradiance is the reference solar input at 1 AU in W/m²; the game divides it by distance in AU squared. The Sun prefab dropdown lists installed sun resources with the Light component required by the game. It controls lighting and is separate from the primary body's identity and visible skybox objects. An imported ID that is not found is retained. Ambience sound and skybox material IDs also reference existing resources; typing a new name does not create one."),
            ("Visual scale and celestial clock", "Celestial body scale and skybox scale change the appearance of the sky. They do not change physical orbital distance. Clock offset days, hours, minutes and seconds shift the initial celestial clock. They do not set the duration of a game day. Some source worlds leave components unspecified; keep source values unless you intend to supply a new offset.")
        },
        new (string Title, string Body)[]
        {
            ("Gas amounts and composition", "Choose a gas from the dropdown, enter Amount (mol), then press Add gas. The amount is moles per 8,000-litre atmosphere cell, not a percentage. Edit the listed quantities to change the mixture. Remove gas beside a gas entry deletes it from this world's atmosphere; it can be added again from the dropdown. Removing every gas creates a vacuum mixture. The colored composition bar always represents the whole mixture; the legend reports each gas's share and amount. Gas temperature is controlled by the world temperature settings rather than a separate temperature for each added gas."),
            ("Pressure estimate", "The reference temperature beside Pressure estimate is only a calculator input. It does not edit the world temperature. The result is a gas-only ideal-gas estimate rather than a complete simulation of liquid content or phase changes. Empty or invalid inputs show - kPa. Actual in-game pressure also depends on atmospheric conditions and changes between gas and liquid."),
            ("Base temperature and sun angle", "The base curve gives an absolute temperature for each sun angle. Zero degrees means overhead sun, 90 degrees is the horizon and 180 degrees is night on the opposite side. This is a 0-180 degree angle, not a 24-hour clock or a full orbital revolution. Click empty graph space to add a point, or drag an existing point. The point list below lets you enter exact angle and temperature values or remove points."),
            ("Display units and graph scale", "Kelvin, Celsius and Fahrenheit change how temperatures are displayed and entered; the XML stores the base temperature in kelvin. The graph bottom corresponds to 0 K. Scale top is always entered in kelvin. Leave it empty for automatic scaling. A requested top below the highest existing temperature cannot hide that point; the display raises the top to include it. Scaling the graph does not change a point's stored temperature."),
            ("Solar, greenhouse and density offsets", "Offsets add to the base temperature. Their values are temperature changes, so a 10 K offset also means a 10°C change. Solar-radiation curves use a relative sunlight input from 0 to 100 across the calculated orbital irradiance range. Greenhouse curves use the combined greenhouse index. Density curves use gas concentration in mmol/L. Day and Night curves define different adjustments; the game blends them around the day/night transition. The XML name Time means curve input here, not clock time."),
            ("Combined-temperature preview", "The preview combines the base, sunlight, greenhouse and density contributions using the game's curve evaluators. The colored buttons show or hide each line. Inspect sun angle selects the position used by the breakdown card. Relative sunlight level selects the input to the solar-radiation curves. These sliders are preview inputs. They do not rewrite world settings. This initial-world calculation excludes active weather, phase-change energy and player heat input."),
            ("Gas greenhouse response", "The gas dropdown selects a response curve to inspect. Its horizontal axis is concentration in mmol/L; its vertical axis is a contribution to the greenhouse index. Contributions from the mixture are added together, then the world's greenhouse temperature curves turn the combined index into a temperature change. The table lists the current concentrations and contributions. Response definitions come from loaded game data, or installed terraforming.xml when no definitions are loaded; this view does not edit those shared definitions."),
            ("Gas phase reference", "The reference card reads triple-point and critical-point temperatures and pressures using the installed game's gas-property calculations. Select a condensable gas to inspect it. These values describe the material; they do not predict when the project's mixture will condense. Climate and pressure previews run on project-owned data and do not require a loaded world or change live game state."),
            ("Pressure fluctuation estimate", "Pressure is estimated from gas moles and the combined temperature curve using P = nRT/V in a fixed 8,000-litre cell. The first graph shows pressure across sun angles at the selected sunlight input. The seasonal graph solves the configured eccentric orbit at equally spaced times, calculates changing distance and inverse-square sunlight, then shows the lowest and highest sampled sun-angle pressures. Its axis is elapsed game days from closest approach when the orbital period is available. A circular orbit has no distance-driven variation. For a planet orbiting its star directly, a pink line also samples pressure at the landing coordinates using the applied rotation and axis. Its one-degree orbital sampling can miss rapid daily changes. Nested moon lighting is not modelled. The gas quantity remains fixed: condensation, evaporation, weather and thermal lag are excluded."),
            ("World conditions", "Maximum sun intensity limits apparent sunlight and lighting; it is separate from orbital distance and the atmosphere's base temperature. Global atmosphere Volume, when present, is the effective simulation volume in litres, separate from one 8,000-litre cell.")
        },
        new (string Title, string Body)[]
        {
            ("Installed weather versus My Saved Weather", "Installed Weather lists available game or source-world events. Add to world assigns the selected event; Remove from world excludes it from this project. This does not delete an installed preset. My Saved Weather lists your reusable custom effects. It has its own dropdown so personal saves stay separate from installed examples."),
            ("Create a custom effect", "Enter a Weather ID beginning with WCWeather_ and a readable display name. Create blank effect supplies initial timing and effect values. Copy selected event uses the selected installed event as a starting point for an independent custom effect. Edit the resulting event card below. The game name key is a localization identifier, not a duration or weather type; the new effect's generated key is a suitable starting value."),
            ("Cooldown, start delay and duration", "Cooldown minimum and maximum are measured in game days. Start delay minimum and maximum are seconds before the event becomes active. Duration minimum and maximum are active seconds. Keep each minimum less than or equal to its maximum. Cooldown 0 does not disable an event. Natural weather also has the game's initial scheduling delay, so shorter values do not guarantee a storm immediately on day zero."),
            ("Temperature, sunlight and gameplay", "Day and night temperature offsets are changes in kelvin added while the event runs. Movement speed uses a multiplier: 1 keeps the baseline speed, and values below 1 reduce it. Damage multiplier scales the event's weather-damage contribution; 0 removes that contribution. Solar ratio changes the event's sunlight contribution. Wind strength and direction configure the weather's wind parameters. Wind strength has no confirmed physical unit in this editor; compare it with an installed event rather than treating it as metres per second."),
            ("Visual effect cards", "Custom effects can add Fog, Storm effect and Directional light cards. Fog controls color and any available distance settings. Storm-effect settings describe the rendered cloud or storm layers, including scale, density, textures and colors. Directional-light settings describe its intensity, frequency and color. Removing a card removes that XML block. Repeated cards remain separate in the editor, but the game's schema may consume only one block of a given type; repeated cards do not guarantee several simultaneous rendered effects."),
            ("Audio and availability", "Wind sound enabled controls the event's wind-audio flag. Shell sound slots refer to existing game sound resources; the editor supports up to four slots where this event format permits them. Can occur in orbit marks the event's orbital availability. These flags change the event definition. They do not start a weather event by themselves or create a new audio file."),
            ("Save, delete and reuse", "Choose Save to My Weather on a custom event's card to keep its current definition in your personal on-disk library. Those saves remain available after restarting the game and in future projects. Delete saved effect removes the personal library copy after confirmation. A copy already added to the open project stays there. Remove from world instead changes only this world's event list. Create world mod includes the events assigned to the world.")
        },
        new (string Title, string Body)[]
        {
            ("Parent body and playable body", "Choose Parent body / tidal-lock target in Orbital elements to set which body this planet or moon orbits. The dropdown lists bodies already present in this world's simulation and its primary body; self-parenting and circular parent chains are excluded. Tidal locking uses this same parent. Changing it updates the draft immediately but does not convert orbital distance or period, so review both. The playable body is the planet or moon being edited. Changing a readable world name does not rename celestial IDs."),
            ("Distance, period and orbit shape", "Average orbital distance is the semi-major axis. Use the displayed unit, AU or kilometres; these are alternate ways to describe orbit size. Orbital period is the time for a full orbit in simulated game days. Eccentricity controls shape: 0 is circular, larger values stretch the ellipse, and an elliptical orbit must stay below 1. Periapsis is the closest approach and apoapsis the farthest point. The editor's readouts help compare them."),
            ("Orbit orientation", "Inclination tilts the orbital plane relative to its reference plane. Orbit plane angle, or longitude of ascending node, turns that plane around the reference axis. Closest approach angle, or argument of periapsis, turns the ellipse within its own plane. Longitude at epoch sets a reference position at the orbital epoch. These are different controls; changing one is not equivalent to rotating the planet's spin axis."),
            ("Rotation mode", "In Rotation & axis, choose Rotation period for a signed duration in simulated days, Rotation speed for a signed rate in degrees per simulated day, or Tidally locked to parent. A negative period or speed requests the native retrograde mode. Values must be finite and nonzero. Tidal locking follows the body's orbital period and names the parent it locks to. A moon locked to its planet still sees the star move as the parent system orbits. Direct star locking can change the game's day counter and day-based weather; check a newly created world before sharing it."),
            ("Set the rotation axis", "Axis tilt from reference Y ranges from 0 to 180 degrees: 0 points up and 180 points down. Axis direction ranges from -180 to 180 degrees and turns the tilted axis around reference Y; 0 points towards +X and 90 towards +Z. This reference-plane tilt is different from orbital inclination. The readout shows the applied XYZ vector and its angle to the body's orbital-plane normal. Apply rotation saves these controls to the draft as one native rotation element and a normalized nonzero axis. Loading a world preserves its original axis until Apply. Saving over a local export still needs the Update confirmation."),
            ("Example: a locked world", "1. Load a world or create one with orbital data. 2. On Orbit & seasons, check its positive orbital period and parent body. 3. Choose Tidally locked to parent, select its Tidal-lock target, and set the axis tilt and direction. The target is also the orbit parent; changing it requires reviewing orbital distance and period. 4. Choose Apply rotation. 5. Use Landing site and Simulate to inspect the lighting; the preview does not edit the starting time. 6. Create a separate world mod and test a fresh world, including clock progression and weather. Locking to a planet is different from locking directly to the star."),
            ("Celestial appearance", "RGB uses three comma-separated values from 0 to 1, for example 0.9,0.5,0.3 for red, green and blue. The colour square previews the result. Incomplete or out-of-range entries must be corrected before export. This changes the celestial body's colour, not the terrain texture. Sunrise offset is an angular adjustment to sunrise/sunset alignment. Rotation and orbital periods are separate controls."),
            ("Landing reference coordinates", "Latitude runs from -90 degrees at the south pole to +90 at the north pole; 0 is the equator. Longitude runs from -180 to +180 degrees around the body. These coordinates locate the playable reference on the celestial surface. They are separate from any terrain-map start-location coordinates or lander spawn definitions. The red marker in Landing site is an illustrative coordinate reference, not a terrain-height or safe-landing guarantee."),
            ("Camera views, spheres and lighting", "Above (XZ), Side (XY) and 3D use the same 3D scene with different camera angles, including depth occlusion between bodies and the orbit path. Landing site provides a close-up coordinate preview. Drag in the interactive views to rotate it. Zoom changes the display size; Reset view restores the camera. The centered XYZ lines are orientation references. Available body textures are used where supported, with a fallback color otherwise. Preview sphere size and lighting are visual aids rather than an accurate physical scale or a full simulation of eclipses."),
            ("Gas properties and the Environment layout", "World Conditions is first. Atmosphere contains the gas amounts in mol beside each gas name, so quantity edits and removal are in one place. Temperature key editors are grouped as baseline plus solar day/night (three columns), greenhouse day/night (two) and density day/night (two); narrow windows wrap them to fit. Gas Phase Reference reads Stationpedia values from the installed game: specific heat, latent heat, freezing and boiling temperatures, minimum condensation pressure and maximum liquid temperature. Its pressure-temperature plot supports logarithmic pressure, Celsius and one comparison gas. The light chart matches Stationpedia: black is the selected gas boundary, orange is a comparison, blue marks freezing, and Solid/Liquid/Gas labels appear when viewing one gas. Hovering shows crosshairs and boundary values. Hover a temperature in the supported liquid range to read boundary pressure. These pure-gas properties are reference values: the world's mixture can condense according to partial pressures and actual simulation conditions. This chart does not predict how much liquid forms over time."),
            ("Asset imports and drop folders", "File imports belong on Asset Libraries. Choose a file there, or choose a source folder and drag supported files into it using Explorer. Refresh folder imports PNG/JPG/JPEG/DDS/TIF/TIFF/RAW/DATA/DAT files, including subfolders, into the selected library category. Unchanged files are skipped; changed files create separate copies. The source folder is remembered across restarts. Originals are never moved or deleted. This refresh does not run a background watcher. Surface and terrain-source dropdowns use compatible library assets; PNG is currently required for new celestial surfaces. A created body retains its selected surface bytes even if the library copy is later removed. Exports package the project's selected assets. The local library remains on this PC; share exported worlds to include their chosen assets, or back up the whole library folder to move the reusable collection."),
            ("Create and select celestial bodies", "Parent and tidal-lock target dropdowns include native bodies and definitions found in installed local and Workshop mods. Missing bodies and their ancestors are copied into the draft. A central body such as Janus replaces the system root and its reference irradiance; review the playable orbit and the sun prefab on Overview. Circular parent chains are excluded. To create a planet or moon: 1. Open Asset Creator and choose Create celestial body. 2. Enter a unique name. 3. Pick an appearance template and parent. 4. Choose AU or km and set a positive distance, period and radius, eccentricity below 1, and inclination. 5. Import an original PNG on Asset Libraries, then choose it in the surface-texture dropdown; a 2:1 image wraps around a sphere. 6. Create body, then select it as the playable world's parent if desired. A moon orbiting the playable world cannot also be its parent. Exports give additional orbital definitions private IDs and copy third-party or original textures. Primary star / central body creates a new light reference. Set its visual in Asset Creator. A planet texture does not change terrain masks or the rocket Space Map."),
            ("Phase and Simulate", "Position along orbit changes the preview's current mean orbital phase. Simulate animates it; In orbital views, 1x means one orbit per minute. Landing site uses a separate pace: 1x is one body rotation per minute, so long years do not cause frantic spinning. Choose 0.1x, 0.25x or 0.5x to slow either view; preview speed never changes the saved rotation or orbital period. The globe uses the applied rotation mode and axis. In Landing site the globe's coordinate frame stays fixed while lighting moves relative to it. Camera drag, zoom, phase and simulation controls do not change world XML. Parent-star lighting and eclipses in nested moon systems are not simulated."),
            ("What the created mod changes", "Edited orbital data is packaged using a world-specific celestial-body definition and references where the editor supports that source. Installed vanilla definitions stay untouched. The preview helps inspect shape and coordinates, but unusual parent-body arrangements, rotation rules and extreme orbital values still need a check in a newly started game world.")
        },
        new (string Title, string Body)[]
        {
            ("Resource profiles and regions", "This page lists resource profiles referenced by the world. A profile defines what can be generated; its conditions and linked Map Studio regions determine where it applies. A profile ID is not necessarily a region ID. A blank world may have no resource profiles to edit."),
            ("Ore density", "Ore density changes the number of vein-generation attempts for a surface profile. 1 keeps the baseline, 0 prevents veins from that profile, and 2 doubles attempts. The game supports 0–10. Terrain, lava and placement conditions still affect the result, so this does not guarantee a proportional amount of usable ore."),
            ("Surface and deep resources", "Surface-resource entries and deep-resource entries are separate definitions. Editing a surface-region density does not automatically change a deep-mining profile. Keep the region ID and the resource profile it references consistent. Detailed ore mixes, vein shapes and deep-mining quantities may be contained in other existing XML records, rather than in a simple density field on this page."),
            ("How map regions affect resources", "A region mask can determine where a linked resource definition applies. Map studio edits those mask pixels; it does not automatically invent a new ore profile for every painted color. A complete custom layout needs both the resource definitions and the region references they use. Changing an ID without updating its links can leave a region without the intended resources."),
            ("What is preserved", "Existing shared resource definitions are retained by their references. This page does not provide a full recipe or ore-vein authoring system. For a small change, adjust the exposed regional values. For source-specific settings, inspect their existing records in Advanced and retain unknown fields unless their behavior is understood."),
            ("Check the resulting world", "Create world mod saves the edited resource values, but the preview does not show generated underground veins. Check the resulting terrain and mining behavior in a newly started world. If a blank definition lacks the resource records needed for your design, begin from a suitable existing definition or supply correctly linked XML records; the density controls alone cannot create a complete resource setup.")
        },
        new (string Title, string Body)[]
        {
            ("Terrain geometry and map images", "Terrain is the physical ground used by the game. Region masks, minimaps and ground textures are images associated with that world; they are not a replacement for compiled terrain geometry. A blank project's basic TerrainSettings entry does not generate a playable landscape by itself."),
            ("Read the terrain summary", "The summary shows the terrain path, world size, curvature, minimap and runtime lava height texture. Crust and crack maps are compilation inputs; they do not have separate runtime map fields. This game build has no BacksplashMap terrain setting. World size is the game's terrain-size value, not a kilometre measurement. Use dimensions compatible with the terrain files you compile or reuse."),
            ("Add a source map", "Choose Heightmap, Crust, Cracks or Lava in Source type. Browse opens a file picker; you can also enter a full local path. Heightmaps must be headerless little-endian float32 data with exactly WorldSize × WorldSize samples. Crust, crack and lava sources use PNG. Validate and add source records the file for packaging. It does not compile terrain automatically. For crust or cracks, import that PNG in Terrain Tools, compile and save the terrain, then select the compiled folder here."),
            ("Set the lava surface", "Choose Lava as the source type, browse to a square power-of-two PNG at least 256 × 256, and enter whole minimum and maximum heights between 0 and 1023, with minimum below maximum. Choose Use PNG as lava surface to package the image and set TerrainSettings/Lava/HeightTexture, its height range and HasLava in the exported world. Black means minimum height; white means maximum. Use the same image and heights for Terrain Tools' lava import so the compiled ground and runtime lava agree. Changing the lava surface does not recompile or carve terrain."),
            ("Use the game's Terrain Tools", "Open Terrain Tools opens the game's own terrain utility without a console command. World Creator hides while that utility is open. Use its import and compilation controls, then reopen World Creator from the main menu to continue the same project. The utility is a separate game tool; its controls are not embedded in the Terrain page."),
            ("Select compiled terrain", "Enter the folder containing the terrain utility's indexed Terrain<number>.dat output and choose Use compiled terrain. The editor validates the supported indexed files and packages selected chunks under this world's GameData/Worlds folder. Keep source maps and compiled output distinct: adding a source heightmap alone does not select compiled chunks."),
            ("Existing worlds and blank worlds", "An existing source world can retain references to its original compiled terrain when no replacement is selected. A blank world has no complete original landscape to reuse, so supply appropriate compiled terrain before expecting it to load as a playable custom landscape. Applying a world preset replaces the current project after confirmation; do that before custom work you need to keep."),
            ("File paths and previews", "Input fields accept local paths while you work. The created mod uses its packaged relative paths and required game resources. A PNG preview confirms that an image can be decoded; it does not verify the final ground shape or safe spawn locations. Keep the original authoring files outside the game mod folder so you can compile them again later.")
        },
        new (string Title, string Body)[]
        {
            ("What Advanced contains", "Advanced exposes the existing world's XML attributes and leaf values, including numeric, text and boolean fields. Paths show the record each value belongs to. It is intended for settings that are source-specific or not covered by a guided card. Unrecognized existing nodes are retained when the world mod is created."),
            ("Find a setting", "Type in Search to filter cards immediately by their field names, XML paths or current values. Search is case-insensitive and keeps all fields of each matching card together. Clear the text to show every card again. Filtering never changes or deletes settings."),
            ("Missing textures", "If export reports a missing image, its error card offers Generate and use texture. Enter a colour as RGB (0–255), check the swatch, choose a square power-of-two size from 16 to 4096, then generate. The opaque PNG is assigned to that field and packaged when you export again. Original game and Workshop files are untouched. Roughness uses brightness; a flat normal is usually 128,128,255. A solid mask fills the whole map with one value. Match paired texture sizes where required, such as albedo and emissive. This is a flat replacement, not reconstruction of the missing artwork."),
            ("Numbers, text and checkboxes", "Use a decimal point for numbers. Keep minimum and maximum values in the correct order. Text fields often contain exact resource IDs or relative file paths. Checkboxes represent true/false settings. A familiar XML name does not guarantee a familiar unit: Time on an atmosphere curve can mean sun angle, concentration or another input instead of seconds."),
            ("IDs and file references", "An ID connects one record to another; a file path points to an asset expected by the game loader. Changing only one side of a reference can disconnect it. A referenced file must be packaged in the world mod or supplied by the installed game or another required mod. Entering a new ID or path does not create the referenced object."),
            ("Curve shape controls", "InTangent and OutTangent are slopes on either side of a curve point. InWeight and OutWeight influence how strongly the curve follows those directions. WeightedMode selects which weights are active. Guided curve editing preserves these shape settings. Change them here only when you want to adjust interpolation rather than just move a point. The calculated climate preview uses the game's weighted curve evaluation."),
            ("Scope and checking changes", "Advanced edits the world records loaded into this project. It is not a general editor for every shared game-data file, recipe or per-gas greenhouse response definition. Avoid giving the same setting conflicting values in guided and Advanced fields. Create world mod checks supported inputs and references, but an unfamiliar setting's full behavior may still require an in-game check.")
        },
        new (string Title, string Body)[]
        {
            ("Layers and region colors", "A region mask is an image whose exact RGB colors identify regions used by world data. Layer checkboxes control which overlays are visible. A selected paint layer and region determine which color a brush writes. Technical IDs are managed automatically; use Advanced for them. Viewing a layer alone does not change it. Painting a new color does not automatically create a matching ore, spawn or environment profile."),
            ("Space Map", "The Space Map dropdown selects an existing rocket destination map, including its travel connections and Low Orbit hub. This is separate from the terrain and region masks. The selector references a definition; it does not create or copy its nodes. Built-in maps come from rocketlocations.xml. Maps defined by another mod require that provider mod to stay enabled. An unknown current ID is preserved instead of silently replaced. The summary shows only definitions found in installed game data or the loaded world's mod folder."),
            ("Create a geographic layer", "On a world without one, Create geographic layer adds a new geographic mask and its required region records. Add named region creates another region with its own identifier and color. Enter a readable region name where the name field is available, select that region, and paint its area. Region names and their localization records are included when the world mod is created."),
            ("Playable-area shapes", "Only Map Layers sits to the right of the map; editing tools are below it. Select the playable-bounds mask first, then choose Playable area in the Tool menu and Polygon, Square or Circle. The tool is unavailable for other masks. Polygon corners move independently. Click an edge or use Add corner to add points; Remove corner removes the selected point while retaining at least three. Up to 128 corners are supported, including concave outlines, but edges cannot cross. Drag inside a shape to move it. Square corners resize equal sides; the circle edge changes its radius. Centre area returns the active marker to the middle of the map. Apply area generates a private green playable mask, blue warning band and red out-of-bounds area. It replaces the draft rules while preserving source masks and compiled terrain. Existing rectangular boundaries seed the initial shape; other existing masks remain visible as references until you apply a replacement."),
            ("Colours, pipette and undo", "Choose a mask below the map or enable it in Map Layers, then select one of its region colours. The pipette samples the active mask pixel and selects its linked region; it ignores the blended overlay colours. Paint with the same region to extend it, or another colour to replace existing pixels. Choose Pick colour in the Tool menu to use the pipette. Ctrl+Z or Undo restores the latest paint stroke, RGB colour edit, mask import or Restore mask action across masks. It retains up to 20 changes within a 64 MB image budget. It does not undo region names, region additions or deletions, or playable-shape handles. Newly created geographic masks can also erase to their base region. Playable boundaries use the shape tools."),
            ("Zoom and individual pixels", "Use the zoom buttons below the map or mouse wheel over it. Middle-drag pans the enlarged map; Reset map view restores the full map. Brush settings stay visible for every tool. Choose Paint and the 1 pixel brush to change exactly one source-mask pixel on a click. Dragging draws a continuous one-pixel line without smoothing or invented colours. Choose Round brush for a larger brush; its radius is measured in original mask pixels. Zoom changes the view, not the mask resolution. Import a PNG through Asset libraries if needed, then use it as the selected mask. Every visible pixel must match a defined region colour exactly."),
            ("Use a visual guide", "A library PNG, JPG or JPEG can be shown as an editor-only reference image. Use as visual guide changes the background you paint against. That guide is not exported as a game region mask and does not assign terrain settings. Clear visual guide removes the reference from the editor view without deleting the library file."),
            ("Restore or save a mask", "Expand Mask files above the map to import images, restore a mask or save a PNG. Restore mask returns to the source image or blank base, updated to preserve any region deletions. Save mask PNG writes a standalone copy under WorldCreator/MapExports in your Stationeers Documents data. Save mask to library also stores the current painted mask in Asset Libraries under Map / UI, available after restarting the game. It can be chosen as a starting mask for a layer with matching region colours. The PNG stores pixels; it does not copy the region names or XML bindings. Create world mod separately packages edited masks with their world-specific references."),
            ("Points of interest and linked data", "Point-of-interest markers are preview positions derived from their referenced region masks. They help inspect links and are not exact safe-spawn or height measurements. Existing POI, resource and playable-area records still need valid region references. Adding or renaming a region updates the draft XML and exported name records. The internal IDs stay stable so existing links remain connected. RGB edits also recolour existing pixels. Delete is available in every mask: its pixels use the remaining region named in the confirmation, and linked POIs, resource placements and boundary rules are removed. Deleting the final region removes its mask. Deletion clears undo history for that mask and becomes its restore baseline; source files remain unchanged.")
        },
        new (string Title, string Body)[]
        {
            ("Choose an installed profile", "The dropdown lists installed starting profiles with readable names and IDs. Add copy to this world creates a world-specific copy of the selected profile's spawn references. For a profile already referenced by the world, choose Customize before editing its custom data. Existing game definitions are preserved."),
            ("Default, name and removal", "Display name labels the custom starting option. Make default selects the option initially used for this world. Remove removes the option from this world's list. Keep a usable starting option while building a normal playable world. New blank condition has no inherited spawn references, lander or equipment. Add the supplies and player-kit references your world needs before exporting."),
            ("Understand spawn roles", "Spawn ID is an exact reference to an existing spawn definition. World applies when the world is created. Player applies to a joining player, and Respawn to a respawning player. New-player kit and Respawn kit refer to their corresponding equipment roles. Keep the intended event and definition paired; moving a lander reference into a kit role does not convert it into equipment."),
            ("Profile flags", "Brutal mode enables the game's special brutal-start rules for this profile. Terrain edit marks a terrain-editing start. These are special game flags, separate from the world's gravity, gases or ore density. Leave them off for a normal start unless your design deliberately requires the corresponding behavior."),
            ("Build supply crates", "Select one starting option from Starting options in this world. New blank condition starts with no inherited gear. Add supply crate creates an empty crate and opens its slots. Click an object in Equipment Overview, then press Search items beside an empty slot. Search by readable name or prefab ID; only items accepted by that native slot appear. Prebuilt supply kits below the item results include compatible installed crates and tanks such as Construction Supplies. Add kit copies the contents into this slot so later edits affect only this occurrence. Stackable items show Qty and Apply; non-stackable equipment occupies one slot. Use Contents to open a nested bag, crate or tank. Rename changes only this object's displayed name. Remove selected deletes it and its contents."),
            ("Navigate equipment", "Equipment Overview shows player kits by species, landers and named containers. Click + to expand a branch and − to collapse it. Click a name to inspect that object; the highlighted row is the current selection. The Location buttons above the editor show the path from the root to the selected object. Click any ancestor to return there immediately. Technical spawn references and duplicate crate wrappers are hidden in this view while their XML remains intact. Respawn kits are marked separately from new-player kits."),
            ("Tank contents", "Select a tank in the overview or use its Contents button. Gas / Fluid Contents shows each starting gas or liquid amount in moles and its temperature in kelvin. Apply changes that entry; Remove removes only that gas entry. To add another gas or liquid, choose its type, enter amount and temperature, then Add. Values must be finite and non-negative. Imported Celsius, litres or energy actions are preserved until edited; applying an edit saves mol and K. Entries mix when the equipment spawns, so their resulting temperature, pressure and phase can differ. Check your tank's safe pressure and temperature in a test world."),
            ("Game and modded item IDs", "Contents searches the prefab assets available in this installation, including loaded mod items. Choose an empty slot first, then search by name or prefab ID. Results use the native slot type, item restrictions and stack limit. If the supplying mod or a referenced prefab is unavailable, the editor cannot validate it and will block additions to that container. This checks starting inventory placement; it does not run a survival simulation."),
            ("Landers and additional spawns", "Click Edit this equipment to make a private editable copy of a loaded profile. The equipment editor is on the left and the collapsible equipment overview is on the right. On narrow screens the overview appears below the editor. Add another lander creates a separate empty lander; use its empty slots to add individual equipment or complete prebuilt kits. Show spawn references and events reveals the underlying IDs and roles when needed. Player-type alternatives and nested contents are preserved. Removing equipment may make a start impossible to survive. Missing or circular definitions must be resolved before copying. Installed source files remain unchanged."),
            ("What is saved", "Create world mod packages custom starting-condition and supported crate/spawn definitions, plus their generated names. These custom conditions belong to this world project; they do not use the reusable My Saved Weather library. Test both a fresh player's start and respawn behavior if you changed those roles, because they can use different definitions.")
        },
        new (string Title, string Body)[]
        {
            ("Import a reusable file", "Enter the full local path to a supported PNG, JPG, JPEG, DDS, TIF, TIFF, RAW, DATA or DAT file, choose a category, then Import file to library. The library stores a copy and leaves the original file in place. The displayed library folder is the persistent location used by this installation."),
            ("Categories, filters and search", "Surface, Underground, Atmosphere / Sky, Map / UI and Other are organizational categories. Use the type and category filters plus Search to find a file. Changing a category or filter does not apply that file to a world setting. A file named ground.png is not automatically selected as the planet's surface texture."),
            ("Library copy versus project copy", "The library is shared by projects on this computer and remains after the game restarts. Add to project makes a separate copy for the current world. That project copy is included when Create world mod runs. Another computer does not automatically receive your personal library; keep a backup of the library and original files if you need them for later editing."),
            ("Assign the displayed asset path", "Assets in this world shows the relative path that the created mod will use under GameData/Worlds/<world ID>/Assets. Copy that path into the world XML setting that needs the file. Adding a file to the project makes it available; it does not decide whether the file is a ground texture, sky image, map mask or another resource."),
            ("Remove copies independently", "Remove from library asks you to confirm removal of the reusable library copy. The original file and any existing project copy remain. Remove from project excludes that project copy from this world's packaged assets while leaving the reusable library copy available. Check references before removing a file that a world setting still needs."),
            ("Map guides and masks", "Map studio can use suitable library images as visual guides, and supported PNGs as starting region masks. A guide is editor-only. A region mask must match the selected layer's exact region colors and is used by exported world data. Choose the appropriate action in Map studio; importing the image into the library alone does neither."),
            ("Terrain files need terrain setup", "A library can store terrain-related source files, but adding an individual RAW or DAT asset to a project does not compile a landscape or select a complete compiled terrain set. Use Terrain to validate source maps and choose the indexed compiled-terrain folder. Use the library for reusable file copies, and each world page for the actual setting that uses them.")
        },
        new (string Title, string Body)[]
        {
            ("Create celestial bodies", "Choose a planet, moon or primary star. Enter the orbit or irradiance, then create the body in this draft."),
            ("Set a star texture", "Import a surface PNG in Asset Libraries. In Asset Creator choose it under Primary Star Appearance and apply. Adjust diameter, glow and light colour here."),
            ("Export a custom star", "A world using a custom star texture requires World Creator Runtime in LaunchPad. Clear the custom appearance to use the stock sun and drop that requirement on the next export."),
            ("Preview and select a body", "Use Orbit & seasons to inspect your star texture and choose the playable world's orbit parent. The preview uses illustrative sizes."),
            ("Create rocket travel maps", "In Asset Creator set up a map and its destinations. Use the space map selector in Map Studio to select a map for this world.")
        }
    };
}
